          "detail": "正始十年正月甲午，曹爽兄弟俱从魏帝曹芳出洛阳城南谒明帝高平陵；装病蛰伏之太傅司马懿突率子司马师、司马昭及死士占据武库、屯兵洛水浮桥，奉郭太后令闭诸城门罢曹爽兵权。桓范劝曹爽挟天子幸许昌号令天下勤王，爽优柔不决投刀请免，旋被司马懿以谋反罪夷曹爽、何晏、丁谧、邓飏、毕轨、李胜、桓范等三族（夏侯霸奔蜀）。政变终结曹氏宗室辅政，大权尽归司马氏；开创“贵无”本体论（《道德论》《周易注》）之正始玄学领袖何晏死难，同年少年天才王弼亦病卒（年二十四）。",
