          "detail": "景元四年秋八月，司马昭遣征西将军邓艾、镇西将军钟会、雍州刺史诸葛绪率军十八万三路伐蜀。蜀汉大将军姜维自沓中疾退，合廖化、张翼扼守剑阁天险，钟会十余万大军攻之不克、粮运将匮议退。十月邓艾精选劲卒自阴平（今甘肃文县）行无人之地七百余里，凿山通道、以毡自裹转运而下摩天岭，奇袭江油、涪城，于绵竹击斩诸葛亮子卫将军诸葛瞻父子。十一月后主刘禅采光禄大夫谯周策，遣使奉玺绶诣邓艾军前投降，立国四十三年之蜀汉灭亡。",
