          "detail": "景元四年，魏国数学家刘徽完成《九章算术注》九卷并附《重差》（后单行称《海岛算经》）。他在方田章圆田术注中摒弃“周三径一”粗率，创立“割圆术”（“割之弥细，所失弥少，割之又割，以至于不可割，则与圆周合体而无所失矣”），由圆内接正六边形倍增至正192边形得徽率π≈157/50=3.14，再算至3072边形得π≈3927/1250=3.1416，并以出入相补原理与无穷小分割证明阳马、鳖臑体积公式，奠定中国古典数学理论体系高峰。",
