          "detail": "咸熙二年八月辛卯，晋王司马昭病卒，世子司马炎嗣为相国、晋王。十二月丙寅，司马炎逼魏元帝曹奂禅让（封陈留王），于洛阳南郊设坛即皇帝位（晋武帝），国号晋（史称西晋），改元泰始。司马炎惩曹魏孤立宗室致亡之弊，即位伊始便大封叔伯兄弟二十七人为郡王，许其自选国中文武官属并渐掌方镇重兵，埋下日后宗室干政隐患。",
