          "title": "晋武帝颁行《泰始律》确立“准五服以制罪”；司空裴秀绘《禹贡地域图》创“制图六体”",
          "detail": "泰始四年正月，贾充、杜预等历时四年修成《晋律》（《泰始律》）二十篇、620条、27600言及《晋令》四十篇颁行天下，杜预、张斐分别为之作注（“张杜律”）。该律精简苛繁，首次确立“峻礼教之防，准五服以制罪”原则，按宗法丧服亲疏定刑罚轻重，标志儒家礼制彻底融入国家法典。同时司空裴秀主持编绘《禹贡地域图》十八篇并缩绘汉代旧图，在序言中系统提出“制图六体”（分率即比例尺、准望即方位、道里即距离、高下、方邪、迂直以校正地形高差曲折），奠定中国传统科学地图学理论基石。",
