          "detail": "太康元年正月至二月，杜预克江陵、定湘交广诸州，王浑破吴丞相张悌于版桥；益州龙骧将军王濬率水师熔断吴军横江铁锁、焚烧铁锥，乘风破浪连克丹阳、武昌。三月壬寅，王濬舟师先入建业石头城，吴末帝孙皓面缚舆榇诣军门投降（封归命侯），立国五十九年之东吴灭亡。自汉末黄巾、董卓乱起近百年之分裂局面终告结束，四月改元太康，天下户口合245万余户、1616万余口。",
