          "title": "西晋颁行《占田、课田制》与《户调式》，确立品官占田荫客特权并诏罢州郡兵",
          "detail": "平吴之后，西晋颁布土地与赋役根本法制：（1）占田与课田：男子一人占田七十亩、女子三十亩；丁男课田五十亩、丁女二十亩，次丁男半之；（2）户调式：丁男之户岁输绢三匹、绵三斤，女及次丁男为户者半输；（3）品官占田荫客制：一品至九品官按品级占田五十顷递减至十顷，并可合法荫亲属（多者九族、少者三世）及衣食客、佃客（一品置佃客十五户，下至九品一户）免除国家赋役，世家门阀庄园经济至此取得法典保障。同年武帝不听山涛、陶璜苦谏，下诏悉罢州郡武备（大郡仅置武吏百人、小郡五十人），致地方空虚无力抵御日后变乱。",
