          "detail": "太熙元年四月己酉，沉湎怠政（曾与石崇、王恺助奢斗富）之晋武帝司马炎病崩于洛阳含章殿（年五十五）。武帝原拟以汝南王司马亮与皇后父杨骏共同辅政，杨骏乘武帝弥留与杨太后合谋改诏，独任太傅、大都督录朝政；不辨菽麦之太子司马衷即位（晋惠帝），改元永熙，西晋统治集团内部权力倾轧一触即发。",
