          "detail": "元康六年八月，秦、雍二州氐、羌因晋官吏暴虐加上连年大旱饥疫起兵，推氐帅齐万年为帝围泾阳。十一月朝廷遣建威将军周处（少时除三害改过向善之阳羡名将）隶安西将军夏侯骏西讨；梁王司马肜挟私怨逼周处以五千兵击七万敌而绝其后援，周处自旦及暮弦绝矢尽战死于六陌。连岁兵荒致略阳、天水等六郡流民十余万口在巴氏人李特率领下南入巴蜀求食。",
