          "detail": "永兴元年正月，司马颖、司马颙害长沙王司马乂；七月东海王司马越奉惠帝北讨司马颖，大败于荡阴，侍中嵇绍（嵇康子）以身蔽帝血溅御衣而死，张方劫惠帝西迁长安。十月，巴氏流民领袖李雄（李特子）攻克成都自称成都王，建元建兴（306年称帝号“大成”，史称成汉）；同月，被司马颖遣返并州发兵之匈奴五部大都督刘渊于离石左国城（今山西方山南）即汉王位，改元元熙，追尊刘禅以收汉民之心（史称汉赵或前赵）。南北两政权同年自立，标志西晋大一统崩解与十六国时代正式揭幕。",
