          "title": "永嘉之乱：石勒歼晋主力于宁平城，汉赵攻陷洛阳俘晋怀帝，中原衣冠南渡",
          "detail": "永嘉五年三月，东海王司马越忧惧卒于项城；四月王衍率晋军主力十余万奉越丧东归东海，被汉赵石勒轻骑追及合围于苦县宁平城（今河南郸城东北），万箭齐发无一免者，太尉王衍（清谈领袖，临死叹“向若不祖尚浮虚，戮力以匡天下，犹可不至今日”）及宗室诸王被石勒排墙压杀。六月丁酉，汉赵主刘聪遣刘曜、王弥、石勒攻破饥困已极之洛阳，焚毁宫庙陵寝，杀太子司马诠及王公士民三万余人，俘晋怀帝北送平阳（封会稽公、青衣行酒），史称“永嘉之嘉祸”。北方世家大族与百万编户大规模渡淮越江避乱（“衣冠南渡”），开启中国经济文化重心南移之历史转折。",
          "category": "军政征伐",
          "regionId": "zhongyuan",
