          "detail": "太元二十年五月，后燕太子慕容宝等率军八万北伐北魏，拓跋珪坚壁清野诱敌深入至黄河岸；十月燕军粮尽烧船夜遁，十一月己卯行至参合陂（今山西阳高南、内蒙古凉城东北），误以为魏军未追而懈怠无备。拓跋珪精选铁骑两万昼夜疾追，乘晨雾登山突袭燕营，大破燕军，采王建议尽坑燕降卒四五万人，后燕精锐丧尽，翌年老燕主慕容垂亲征亦病死军中，华北霸权归于北魏。",
