          "detail": "元嘉十六年（北魏太延五年）六月，北魏太武帝拓跋焘亲统大军自平城西征河西走廊北凉；九月丙戌，姑臧（今甘肃武威）城陷，北凉主沮渠牧犍率文武五千人面缚出降，北魏收姑臧仓库珍宝并徙凉州吏民、硕儒（宗钦、索敞等）及沙门三万余家充实平城，立国三十九年之北凉灭亡。至此自304年成汉、汉赵建国以来持续百三十五年之“五胡十六国”分裂混战正式终结，北朝（北魏）与南朝（刘宋）全面南北对峙格局最终确立，保存于河西之汉晋经学与凉州石窟技艺深刻滋养了北魏制度与文化。",
