          "detail": "太平真君十一年六月，北魏司徒崔浩因监修《国史》据实直书拓跋氏先世史事并刻石立于平城郊坛通衢，激怒鲜卑贵族与太武帝，遭酷刑处死并夷灭清河崔氏及范阳卢氏、太原郭氏、河东柳氏等北方高门姻亲百二十八人。七月宋文帝轻信王玄谟等虚辞发动大规模北伐，王玄谟围滑台数月不克，十月魏军百万渡河反击，王玄谟军溃散；太武帝拓跋焘亲统步骑长驱南下连破六州，十二月戊午进驻长江北岸瓜步山（今江苏南京六合东南），凿山为道声言渡江，建康内外戒严大震。",
