          "detail": "北魏和平元年（刘宋大明四年），凉州高僧昙曜出任北魏沙门统，倡言“皇帝即当今如来”，奏请于平城西三十里武州塞（今山西大同西云冈）斩山石壁，开窟五所（今云冈第16至20窟，史称“昙曜五窟”），各雕高六七十尺之巨型石佛，其法相隐喻北魏道武、明元、太武、景穆、文成五代帝王。云冈早期造像融汇印度犍陀罗、笈多造像粉本与鲜卑草原雄浑刚健气象，开创中国皇家石窟艺术第一座高峰。",
