          "title": "萧道成受宋禅建立南齐，立校籍官整顿黄籍诈伪",
          "detail": "升明三年四月甲午，累破宗室叛乱、执掌禁军大权之相国齐王萧道成逼十二岁宋顺帝刘准禅位（封汝阴王，寻遇害），于建康南郊即皇帝位（齐高帝），国号齐（史称南齐），改元建元，立国五十九年之刘宋灭亡。萧道成力戒奢靡，并针对寒人庶族贿改户籍假冒士族免役之弊，置校籍官严查“却籍”，还原赋役负担。",
