          "detail": "齐武帝萧赜在位十一年（永明元年483—十一年493），与北魏通好息战、减免逋租、整顿检籍，江南户口殷阜，史称“永明之治”。永明六年二月，太子家令沈约奉敕撰成《宋书》一百卷奏上；同时期竟陵王萧子良于建康鸡笼山西邸延揽沈约、谢朓、王融、萧衍等“竟陵八友”，周颙撰《四声切韵》，沈约系统提出汉语平上去入“四声”与“八病”声律理论，创作讲求声韵和谐对仗之“永明体”诗歌，开启由古体诗向唐代格律近体诗演进之关键转折。",
