          "detail": "太和十九年（南齐建武二年）六月己亥，孝文帝颁诏断诸北语、一从正音：年三十以上习性已久者容或渐改，三十以下见在朝廷之人严禁再说鲜卑语，一律改用中原汉语，若有故违当即降爵黜官；同月诏迁洛之代北鲜卑人死后一律葬于洛阳北邙山，不得归葬平城，籍贯悉改河南洛阳人。同年并诏定门阀姓族品第，以鲜卑穆、陆、贺、刘、楼、于、嵇、尉“勋臣八姓”与汉族范阳卢、清河崔、荥阳郑、太原王“四姓”同列一流高门，按门第授官通婚。",
