          "detail": "中兴二年四月丙寅，平定东昏侯暴政之相国梁王萧衍受南齐和帝禅位，于建康南郊即皇帝位（梁武帝），国号梁（史称南梁），改元天监，立国二十三年之南齐灭亡。梁武帝在位四十八年，天监初政勤于庶务，置谤木、肺石函广纳吏民申诉，并命尚书删定郎蔡法度损益晋律修成《梁律》（《天监律》）二十篇与《梁令》三十卷（翌年四月颁行），开创江南近半世纪相对安定之“天监之治”。",
