          "title": "钟离大捷：韦睿、曹景宗乘淮水暴涨火烧魏军浮桥，大破北魏数十万南侵主力",
          "detail": "北魏宣武帝命中山王元英、平东将军杨大眼统步骑数十万围攻淮水军事要塞钟离（今安徽凤阳东北），填堑架桥昼夜猛扑，梁守将昌义之率三千卒泥土补城浴血死守。梁武帝急命豫州刺史韦睿自合肥驰援，与右卫将军曹景宗会师筑垒；天监六年三月淮水暴涨六七尺，韦睿、曹景宗乘高舰顺风纵火焚毁魏军跨淮两座浮桥，梁军敢死士拔栅猛攻，魏军奔溃争投淮水，斩溺及生擒二十余万，元英单骑脱逃，创南北朝南军对北军最大规模歼灭战大捷，江淮防线稳固四十余年。",
