          "detail": "天监六年，针对佛教盛行下因果报应与灵魂不灭说泛滥，尚书殿中郎范缜撰《神灭论》，鲜明提出“形者神之质，神者形之用；神之于质，犹利之于刀，形之于用，犹刀之于利；未闻刀没而利存，岂容形亡而神在”，直指精神依存于肉体形质。笃信佛教之梁武帝亲撰《敕答臣下神灭论》，命光宅寺法云及沈约、王公朝贵六十余人群起撰文围攻辩难，范缜据理往复抗辩，词锋凛然不屈，树中国古代唯物无神论思想高峰。",
