          "detail": "天监七年二月乙丑，梁武帝采徐勉制定之百官新仪，全面改革魏晋沿袭之九品官品旧制：设文武流内官“十八班”（以班多者为贵，十八班最高如丞相太宰，一班最低；同班之内再按清浊定士庶流品），流外另设“蕴位”三品、“勋位”五品及寒微初入仕之“七班”，精细区分品位阶次与职事清浊，对北朝后期及隋唐散官品阶制度演进深有启迪。",
