          "detail": "北魏神龟元年十一月，临朝胡太后遣敦煌人宋云与崇立寺沙门惠生自洛阳出发西行，经吐谷浑、鄯善、于阗越葱岭，遍访嚈哒帝国及北天竺乌场国、乾陀罗国，历时四年携大乘梵经百七十部归洛阳（事载《洛阳伽蓝记》卷五所引《宋云行纪》）。约在同年（梁天监十二年至十七年卒前），记室参军钟嵘撰成五言诗批评专著《诗品》三卷，品评汉魏至梁百二十二位诗人分列上中下三品，推崇曹植建安风骨，批评沈约“四声八病”人为拘忌，与《文心雕龙》双峰并峙。",
