          "title": "北魏洛阳爆发“羽林之变”：禁军哗变焚杀大臣张彝，胡太后姑息致北魏纲纪崩坏",
          "detail": "神龟二年二月庚午，北魏征西将军张彝之子张仲瑀上封事请求铨削选格、排抑武人不入清品，激怒聚居洛阳、仕途受阻之羽林与虎贲武人千余人。乱兵白昼冲入尚书省哗变，直扑张彝宅第纵火焚屋，将老臣张彝殴打致死、投其二子入火重伤。临朝听政之胡太后（灵太后）震惧不敢追查，仅收斩凶首八人、大赦其余乱兵，并屈服开放武人选官，北魏中枢威信扫地，塞北六镇武人更轻视朝廷。",
