          "title": "梁武帝首次舍身同泰寺；北魏地理学家郦道元殉难关中，遗著《水经注》四十卷传世",
          "detail": "大通元年三月辛未，崇佛日笃之梁武帝萧衍首次驾幸建康同泰寺“舍身”为寺奴，四日后还宫大赦改元大通（此后复于529、546、547年三次舍身，朝臣每次敛公私钱一亿万向寺院“奉赎”皇帝菩萨）。同年十月，奉命赴关中平叛之北魏关右大使、御史中尉郦道元在阴盘驿亭遭反叛之雍州刺史萧宝夤伏兵围杀，瞋目叱贼凛然殉职；其生前以汉桑钦《水经》为纲、博引四百三十余种文献并结合亲身踏勘撰成之《水经注》四十卷，详载一千二百五十二条水道之源流、地貌、水利、城邑、碑刻与历史掌故，集六朝历史自然地理学之大成。",
