          "detail": "武泰元年二月，北魏胡太后鸩杀谋夺军权之十九岁亲生子孝明帝元诩，秘立三岁幼主；统握并肆精锐胡骑之契胡酋长尔朱荣以讨逆为名自晋阳南下，立长乐王元子攸为孝庄帝（改元建义）。四月庚子，尔朱荣将胡太后及幼主沉入黄河，并假借祭天诱骗北魏迁洛元氏宗室王公、汉化鲜卑勋贵与中原士族百官两千余人出至洛阳西北河阴陶渚，命胡骑四面合围尽数屠杀（“河阴之变”），洛阳为之空虚，孝文帝苦心培育之洛阳汉化文官集团遭受毁灭性摧残。九月尔朱荣复以七千精骑于滏口奇袭生擒拥众数十万之河北起义首领葛荣。",
