          "detail": "中大通三年四月乙巳，仁孝博学、礼贤下士之南梁皇太子萧统（谥昭明）病卒于东宫，年仅三十一岁，建康男女奔走宫门号泣。萧统生前聚东宫学士藏书三万卷，以“事出于沉思，义归乎翰藻”为遴选准绳，严格区分经、史、诸子实用文献与审美文学作品，编成诗赋文章总集《文选》三十卷（收录自周代屈宋至梁代百三十家作品），成为中国现存最早之诗文总集与唐宋学子必习经典。同年六月，怀朔镇出身之信都都督高欢起兵反讨残暴之尔朱兆集团。",
