          "detail": "大统七年九月，西魏丞相宇文泰奏请颁行苏绰起草之施政纲领《六条诏书》（一先治心、二敦教化、三尽地利、四擢贤良、五恤狱讼、六均赋役），敕令中外牧守令长日夜习诵，不通六条及计帐法者不得居官。翌年至大统十六年间，宇文泰因邙山战损广募关陇汉族豪右乡兵（给复除免全家租调），编入以“八柱国—十二大将军—二十四开府”统辖之军府体系（府兵制初创），并赐汉将鲜卑姓，凝聚成文武合一、胡汉交融之“关陇集团”。",
