          "detail": "太清元年（东魏武定五年）正月丙午，东魏丞相高欢卒于晋阳，世子高澄嗣掌大权。二月，专制河南十四年、素轻高澄之东魏司徒侯景举河南十三州叛降西魏，旋惧宇文泰猜防而改表献地归附南梁；八十四岁之梁武帝贪图中原虚名，排朝臣苦谏纳侯景封河南王，所遣萧渊明接应大军于寒山惨败被俘，十二月侯景为东魏名将慕容绍宗大破于涡阳，仅率八百残骑南奔袭占梁境寿阳。同年，东魏抚军府司马杨衒之因公务重经迁邺后荒芜残破之故都洛阳，追忆全盛时千余佛寺梵宇与历史掌故，撰成《洛阳伽蓝记》五卷。",
