          "detail": "承圣三年（西魏恭帝元年）十月，西魏宇文泰乘梁元帝萧绎平蜀后骄矜失礼，命柱国于谨、宇文护、杨忠统步骑五万南伐江陵。十一月魏军渡汉水合围江陵，梁元帝犹于龙光殿讲《老子》；十二月辛未城陷，元帝临降前命舍人高善宝将宫廷汇集之古今图书十四万卷悉数焚毁，以宝剑斫柱叹曰：“文武之道，今夜尽矣！”旋被西魏处死（明年西魏立萧詧于江陵为附庸“后梁”），江陵王公百官士民十余万口尽被驱掠入长安没为奴婢，南朝两百年文化典籍精华遭遇空前浩劫。",
