          "detail": "北齐河清三年（南陈天嘉五年）三月，北齐武成帝正式颁行尚书令赵郡王高叡、封述等历时多年删定之《齐律》（《河清律》）十二篇共九百四十九条，同步颁布河清均田租调令。《河清律》融汇汉魏中原律学世家精髓，“法令明审，科条简要”，首次将危害皇权社稷与家族伦常之十类大罪归纳为“重罪十条”（反逆、大逆、叛、降、恶逆、不道、不敬、不孝、不义、内乱），规定犯此十者不在八议论赎之限，成为隋《开皇律》与唐律“十恶不赦”制度之直接蓝本。",
