          "detail": "太建十年（北周宣政元年）二月，南陈大将吴明彻围攻北周彭城，周徐州总管梁士彦固守，大将军王轨引兵至清水入淮口横竖大木、锁铁链截断陈水师归路，大破陈军，生擒吴明彻及将卒三万人，南陈精锐丧尽（翌年韦孝宽南下尽取淮南，南陈退守长江天堑）。同年五月北周武帝宇文邕亲统五道大军北伐突厥欲毕全功，六月丁酉行至云阳宫疾作骤崩，年仅三十六岁，乖戾昏暴之太子宇文赟即位（周宣帝）。",
