          "title": "杨坚受北周禅建立隋朝改元开皇，确立“三省六部制”并颁行《开皇律》五百条",
          "detail": "开皇元年二月甲子，相国随王杨坚受北周静帝宇文阐禅让，于长安临光殿即皇帝位（隋文帝），因恶“随”字从“辶”有奔走不宁之象，遂去“辶”定国号为“隋”，改元开皇，立国二十五年之北周灭亡。杨坚即位伊始即废北周复古《周礼》六官，正式确立中央“三省六部制”：以尚书省总行政（统吏、礼、兵、度支[寻改民/户]、都官[寻改刑]、工六部）、内史省（中书省）草诏决策、门下省封驳审议。同年十月戊子，颁行高颎、郑译、裴政等损益北齐律修成之《开皇律》十二篇五百条，废除枭首轘裂鞭刑等酷刑，定型“笞、杖、徒、流、死”新五刑、八议减赎与“十恶”制度，奠定隋唐至明清一千三百年中华帝国官制与法典总框架。",
