          "detail": "汉代以来长安故城历经战乱残破狭小、地下水咸卤不堪饮用。开皇二年六月丙申，隋文帝下诏于汉长安城东南龙首原南麓择地营建宏伟新都，以宰相高颎总领，天才建筑学家、将作大匠宇文恺任副监具体规划设计，因杨坚曾封大兴公而名“大兴城”（入唐改称长安城）。宇文恺首创宫城、皇城、郭城三重分立且严格沿朱雀大街中轴对称之棋盘式百八里坊格局，面积达84平方公里，成为中古世界最大都城与日韩平城京、平安京营建母本。七月颁行《开皇令》完备均田赋役法制。",
