          "detail": "南陈后主陈叔宝在建康荒于酒色、宠信江总孔范，不修江防。开皇八年三月辛未，隋文帝下诏历数陈叔宝二十大罪，散写玺书三十万纸遍谕江南；十月甲子，置淮南行台省于寿春，命二十岁次子晋王杨广、三子秦王杨俊、清河公杨素并为行军元帅，左仆射高颎为晋王元帅长史总决三军实务，统贺若弼（出广陵）、韩擒虎（出庐州）等东起沧海、西自巴蜀共九十总管、五十一万八千水陆大军全线压境长江北岸。自公元220年曹丕代汉以来分裂近三百七十年之魏晋南北朝大分裂时代至此走入终章，翌年（开皇九年，589）正月隋师渡江克建康，华夏重归大一统。",
